<?php
require_once 'includes/auth.php';require_admin();
$users=get_users();$userId=trim($_GET['user_id']??'');$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');$action=trim($_GET['action']??'');
if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$from))$from=date('Y-m-01');if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$to)||$to<$from)$to=date('Y-m-d');
$rows=cds_audit_read($from,$to,$userId,$action,3000);$selected=$userId!==''?find_user_by_id($userId):null;
$logins=count(array_filter($rows,fn($r)=>($r['action']??'')==='login_success'));$views=count(array_filter($rows,fn($r)=>($r['action']??'')==='page_view'));$changes=count(array_filter($rows,fn($r)=>in_array($r['action']??'',['create','update','delete','export'],true)));$modules=[];$days=[];
foreach($rows as $r){$m=$r['module']??'system';$modules[$m]=($modules[$m]??0)+1;$d=substr($r['at']??'',0,10);$days[$d]=($days[$d]??0)+1;}arsort($modules);$maxModule=max($modules?:[1]);
$labels=['login_success'=>'Đăng nhập thành công','login_failed'=>'Đăng nhập thất bại','logout'=>'Đăng xuất','page_view'=>'Truy cập trang','create'=>'Tạo dữ liệu','update'=>'Cập nhật dữ liệu','delete'=>'Xóa dữ liệu','export'=>'Xuất báo cáo'];
?>
<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Nhật ký người dùng</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css" rel="stylesheet"><style>body{background:#f4f7fb}.wrap{max-width:1450px}.card{border:1px solid #e2e8f0;border-radius:16px;box-shadow:0 4px 18px rgba(15,23,42,.04)}.kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.kpi{padding:17px}.kpi strong{display:block;font-size:25px}.kpi span{color:#64748b;font-size:12px}.profile-head{display:flex;align-items:center;gap:14px}.avatar{display:grid;place-items:center;width:54px;height:54px;border-radius:50%;background:#dbeafe;color:#1d4ed8;font-size:22px;font-weight:900}.bar-row{display:grid;grid-template-columns:100px 1fr 38px;gap:9px;align-items:center;margin:10px 0}.bar{height:8px;border-radius:99px;background:#e2e8f0;overflow:hidden}.bar i{display:block;height:100%;border-radius:inherit;background:#2563eb}.table td{vertical-align:middle}.agent{max-width:270px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}@media(max-width:800px){.kpis{grid-template-columns:1fr 1fr}.filters>div{width:100%}}</style></head><body><?php $nav_title='Nhật ký & hồ sơ 360°';$nav_icon='bi-activity';$nav_color='#2563eb';$nav_module='admin';include __DIR__.'/includes/nav_top.php';?><main class="container-fluid py-4 wrap"><div class="d-flex flex-wrap justify-content-between gap-2 mb-3"><div><h3 class="mb-1">Nhật ký và hồ sơ hoạt động</h3><p class="text-muted mb-0">Theo dõi truy cập và thao tác của từng cán bộ trong một giai đoạn.</p></div><a href="admin.php" class="btn btn-outline-secondary align-self-start"><i class="bi bi-arrow-left"></i> Trang chủ</a></div><form class="card p-3 mb-3"><div class="row g-2 align-items-end filters"><div class="col-md-3"><label class="form-label">Cán bộ</label><select name="user_id" class="form-select"><option value="">Tất cả tài khoản</option><?php foreach($users as $u):?><option value="<?= e($u['id']) ?>" <?= $userId===($u['id']??'')?'selected':'' ?>><?= e($u['name']??$u['username']) ?> · <?= e($u['username']) ?></option><?php endforeach;?></select></div><div class="col-md-2"><label class="form-label">Từ ngày</label><input class="form-control" type="date" name="from" value="<?= e($from) ?>"></div><div class="col-md-2"><label class="form-label">Đến ngày</label><input class="form-control" type="date" name="to" value="<?= e($to) ?>"></div><div class="col-md-2"><label class="form-label">Hành động</label><select class="form-select" name="action"><option value="">Tất cả</option><?php foreach($labels as $key=>$label):?><option value="<?= e($key) ?>" <?= $action===$key?'selected':'' ?>><?= e($label) ?></option><?php endforeach;?></select></div><div class="col-md-2"><button class="btn btn-primary w-100"><i class="bi bi-filter"></i> Xem dữ liệu</button></div></div></form>
<?php if($selected):?><section class="card p-3 mb-3 profile-head"><span class="avatar"><?= e(mb_substr($selected['name']??'U',0,1)) ?></span><div><h5 class="mb-1"><?= e($selected['name']??'') ?></h5><div class="text-muted"><?= e($selected['username']??'') ?> · <?= e(implode(', ',$selected['groups']??[])?:($selected['role']??'')) ?></div><small>Phạm vi lớp: <?= e(($selected['classes']??[])?implode(', ',$selected['classes']):'Toàn trường/chưa giới hạn') ?></small></div></section><?php endif;?>
<section class="kpis mb-3"><div class="card kpi"><strong><?= count($rows) ?></strong><span>Tổng sự kiện</span></div><div class="card kpi"><strong><?= $logins ?></strong><span>Lượt đăng nhập</span></div><div class="card kpi"><strong><?= $views ?></strong><span>Trang đã truy cập</span></div><div class="card kpi"><strong><?= $changes ?></strong><span>Thao tác dữ liệu</span></div></section><div class="row g-3"><div class="col-lg-4"><section class="card p-3 h-100"><h5>Hoạt động theo module</h5><?php foreach(array_slice($modules,0,12,true) as $module=>$count):?><div class="bar-row"><span class="text-truncate"><?= e($module) ?></span><span class="bar"><i style="width:<?= round($count/$maxModule*100) ?>%"></i></span><strong><?= $count ?></strong></div><?php endforeach;if(!$modules):?><div class="text-muted py-4 text-center">Chưa có dữ liệu</div><?php endif;?></section></div><div class="col-lg-8"><section class="card p-3"><div class="d-flex justify-content-between"><h5>Chi tiết nhật ký</h5><small class="text-muted">Tối đa 3.000 dòng</small></div><div class="table-responsive"><table class="table table-hover"><thead><tr><th>Thời gian</th><th>Người dùng</th><th>Hành động</th><th>Module/đường dẫn</th><th>IP · thiết bị</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td class="text-nowrap"><?= e(date('H:i:s d/m/Y',strtotime($r['at']))) ?></td><td><strong><?= e($r['user_name']?:$r['username']) ?></strong><small class="d-block text-muted"><?= e($r['username']) ?></small></td><td><span class="badge text-bg-light"><?= e($labels[$r['action']??'']??$r['action']??'') ?></span></td><td><strong><?= e($r['module']??'') ?></strong><small class="d-block text-muted"><?= e($r['path']??'') ?></small></td><td><span><?= e($r['ip']??'') ?></span><small class="d-block text-muted agent" title="<?= e($r['agent']??'') ?>"><?= e($r['agent']??'') ?></small></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="5" class="text-center text-muted py-5">Không có hoạt động trong giai đoạn đã chọn.</td></tr><?php endif;?></tbody></table></div></section></div></div></main></body></html>
